<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigDcrAllowedGrantTypesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigDcrAllowedGrantTypesAccessor trait.
 *
 * Covers null default, string/VO assignment via withDcrAllowedGrantTypes,
 * getDcrAllowedGrantTypes/dcrAllowedGrantTypes accessors, and isDcrAllowedGrantTypesChanged with/without original.
 */
class TenantConfigDcrAllowedGrantTypesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDcrAllowedGrantTypes creates a new instance with the DcrAllowedGrantTypes set
     * from a string value, and getDcrAllowedGrantTypes returns the primitive string.
     */
    public function testWithDcrAllowedGrantTypesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDcrAllowedGrantTypesAccessorUnitTest();

        // Act
        $result = $holder->withDcrAllowedGrantTypes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDcrAllowedGrantTypes());
    }
    /**
     * Asserts that withdcrAllowedGrantTypes has access to the value object
     * from a string value, and getDcrAllowedGrantTypes returns the primitive string.
     */
    public function testWithDcrAllowedGrantTypesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDcrAllowedGrantTypesAccessorUnitTest();

        // Act
        $result = $holder->withDcrAllowedGrantTypes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->dcrAllowedGrantTypes()->value());
    }
    public function testChangedDcrAllowedGrantTypes(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDcrAllowedGrantTypesAccessorUnitTest();
        $original = $holder->withDcrAllowedGrantTypes('one');
        $same = $holder->withDcrAllowedGrantTypes('one');
        $modified = $holder->withDcrAllowedGrantTypes('other');

        // Act
        $unchanged = $holder->isDcrAllowedGrantTypesChanged();
        $withSame = $original->isDcrAllowedGrantTypesChanged($same);
        $withDiferent = $original->isDcrAllowedGrantTypesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigDcrAllowedGrantTypesAccessorUnitTest
{
    use TenantConfigDcrAllowedGrantTypesAccessor;
}
